    const [nx, nz] = outN(P, i), n = Math.max(1, Math.round(L/sp)), ux = ex/L, uz = ez/L, yy0 = typeof y0 === 'function' ? y0 : () => y0, yy1 = typeof y1 === 'function' ? y1 : () => y1;
