  for (const [P, yb, yt, dx, dz] of [[F.T3a, 206, 239, -0.3, -0.95], [F.T3c, 206, 238, 0.3, 0.95], [F.T3b, 206, 218, 0, -1], [F.T3d, 206, 218, 1, 0]]){
    const f = slopeF(P, yb + (yt - yb)*0.45, yt, dx, dz); prismP(B.p(crown), P, yb - 0.02, f); mullP(B.p(mull), P, yb, f, 3.0, 0.3, 0.14); edgeLineP(B.p(line), P, f, 0.35); }
