  LPolyD(g, F.POD, 29.4, 0.6, lawn);
  // the City Room: tall glazing on the tower's base facing the Urban Park (east)
  { const P = F.TW; let best = 0, bi = 0; for (let i = 0; i < P.length; i++){ const [nx] = outN(P, i); if (nx > best){ best = nx; bi = i; } }
    const a = P[bi], b = P[(bi+1) % P.length], [nx, nz] = outN(P, bi), q = 4.3;
    quadP(B.p(glz), [a[0] + nx*q, 0.3, a[1] + nz*q], [b[0] + nx*q, 0.3, b[1] + nz*q], [b[0] + nx*q, 26, b[1] + nz*q], [a[0] + nx*q, 26, a[1] + nz*q]); }
  // pool and trees on the podium roof (west of the tower)
