  treesIn(B, F.POD, 28, 30, 0.9, r, (x, z) => inPoly(F.TW, x, z) || dPoly(F.TW, x, z) < 3 || inPoly(F.HOT, x, z) || dPoly(F.HOT, x, z) < 3);
  // the tower: full plan to 180 m, north half on to 280 m; fins all the way up
